src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>

template <int TPB>
__global__ void compute_mean_kernel(const half* __restrict__ x,
                                    float* __restrict__ mean,
                                    int N, int H, int W, int C) {
    const int c = blockIdx.x;                     // channel index
    const int tid = threadIdx.x;
    const int stride = blockDim.x;
    const int HWN = N * H * W;
    float sum = 0.0f;

    // linear index within a channel
    for (int idx = tid; idx < HWN; idx += stride) {
        int n = idx / (H * W);
        int hw = idx % (H * W);
        int offset = ((n * C + c) * H * W) + hw;
        half v = x[offset];
        sum += __half2float(v);
    }

    // reduction in shared memory
    __shared__ float sdata[TPB];
    sdata[tid] = sum;
    __syncthreads();

    #pragma unroll
    for (int s = TPB / 2; s > 0; s >>= 1) {
        if (tid < s) sdata[tid] += sdata[tid + s];
        __syncthreads();
    }

    if (tid == 0) {
        mean[c] = sdata[0] / static_cast<float>(HWN);
    }
}

template <int TPB>
__global__ void compute_var_kernel(const half* __restrict__ x,
                                   const float* __restrict__ mean,
                                   float* __restrict__ var,
                                   int N, int H, int W, int C) {
    const int c = blockIdx.x;
    const int tid = threadIdx.x;
    const int stride = blockDim.x;
    const int HWN = N * H * W;
    float m = mean[c];
    float sum = 0.0f;

    for (int idx = tid; idx < HWN; idx += stride) {
        int n = idx / (H * W);
        int hw = idx % (H * W);
        int offset = ((n * C + c) * H * W) + hw;
        half v = x[offset];
        float diff = __half2float(v) - m;
        sum += diff * diff;
    }

    __shared__ float sdata[TPB];
    sdata[tid] = sum;
    __syncthreads();

    #pragma unroll
    for (int s = TPB / 2; s > 0; s >>= 1) {
        if (tid < s) sdata[tid] += sdata[tid + s];
        __syncthreads();
    }

    if (tid == 0) {
        var[c] = sdata[0] / static_cast<float>(HWN);
    }
}

template <int TPB>
__global__ void apply_bn_kernel(const half* __restrict__ x,
                                half* __restrict__ y,
                                const float* __restrict__ mean,
                                const float* __restrict__ var,
                                const half* __restrict__ weight,
                                const half* __restrict__ bias,
                                const float eps,
                                int N, int H, int W, int C) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = N * C * H * W;
    if (idx >= total) return;

    // decode indices
    int tmp = idx;
    const int w = tmp % W;          tmp /= W;
    const int h = tmp % H;          tmp /= H;
    const int c = tmp % C;          tmp /= C;
    // const int n = tmp; // not needed

    const int offset = idx;
    half v = x[offset];
    float x_f = __half2float(v);
    float m = mean[c];
    float vvar = var[c];
    float inv_std = rsqrtf(vvar + eps);
    float w_f = __half2float(weight[c]);
    float b_f = __half2float(bias[c]);
    float y_f = ((x_f - m) * inv_std) * w_f + b_f;
    y[offset] = __float2half(y_f);
}

// -------------------------------------------------------------------
// C++ interface
// -------------------------------------------------------------------
torch::Tensor batchnorm_forward_cuda(torch::Tensor x,
                                     torch::Tensor weight,
                                     torch::Tensor bias,
                                     const float eps) {
    const int N = x.size(0);
    const int C = x.size(1);
    const int H = x.size(2);
    const int W = x.size(3);
    const int threads = 256;          // must be power of two
    const dim3 grid_mean(C);
    const dim3 grid_var(C);
    const int total = N * C * H * W;
    const dim3 grid_apply((total + threads - 1) / threads);

    auto y = torch::empty_like(x);
    auto mean = torch::empty({C}, torch::dtype(torch::kFloat32).device(x.device()));
    auto var  = torch::empty({C}, torch::dtype(torch::kFloat32).device(x.device()));

    AT_DISPATCH_HALF_TYPES(x.scalar_type(), "compute_mean_kernel", ([&] {
        compute_mean_kernel<threads><<<grid_mean, threads>>>(
            reinterpret_cast<const half*>(x.data_ptr()),
            mean.data_ptr<float>(),
            N, H, W, C);
    }));

    AT_DISPATCH_HALF_TYPES(x.scalar_type(), "compute_var_kernel", ([&] {
        compute_var_kernel<threads><<<grid_var, threads>>>(
            reinterpret_cast<const half*>(x.data_ptr()),
            mean.data_ptr<float>(),
            var.data_ptr<float>(),
            N, H, W, C);
    }));

    AT_DISPATCH_HALF_TYPES(x.scalar_type(), "apply_bn_kernel", ([&] {
        apply_bn_kernel<threads><<<grid_apply, threads>>>(
            reinterpret_cast<const half*>(x.data_ptr()),
            reinterpret_cast<half*>(y.data_ptr()),
            mean.data_ptr<float>(),
            var.data_ptr<float>(),
            reinterpret_cast<const half*>(weight.data_ptr()),
            reinterpret_cast<const half*>(bias.data_ptr()),
            eps,
            N, H, W, C);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA error: ") + cudaGetErrorString(err));
    }
    return y;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("batchnorm_forward", &batchnorm_forward_cuda, "BatchNorm forward (fp16)");
}
'''

# ------------------------------------------------------------------------
# Compile the inline extension
# ------------------------------------------------------------------------
bn_ext = load_inline(name='bn_ext',
                     cpp_sources='',
                     cuda_sources=src,
                     functions=['batchnorm_forward'],
                     verbose=False)

# ------------------------------------------------------------------------
# Model implementing the custom BatchNorm2d
# ------------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self, num_features: int, eps: float = 1e-5):
        super().__init__()
        self.eps = eps
        # weight and bias as fp16 parameters (affine=True)
        self.weight = nn.Parameter(torch.ones(num_features, dtype=torch.float16))
        self.bias   = nn.Parameter(torch.zeros(num_features, dtype=torch.float16))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ensure input is contiguous and on the same device as parameters
        x = x.contiguous()
        self.weight = self.weight.to(x.device)
        self.bias   = self.bias.to(x.device)
        return bn_ext.batchnorm_forward(x, self.weight, self.bias, self.eps)

# ------------------------------------------------------------------------
# Helper functions matching the original reference API
# ------------------------------------------------------------------------
def get_inputs():
    batch_size = 64
    features = 64
    dim1 = 512
    dim2 = 512
    x = torch.rand(batch_size, features, dim1, dim2, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    return [64]   # num_features

# Example usage (not executed in the harness)
if __name__ == "__main__":
    model = ModelNew(num_features=64).cuda()
    inp = get_inputs()[0]
    out = model(inp)
    print(out.shape, out.dtype)
